const VALIDATORS: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
};

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = VALIDATORS[message.type];
  if (validator) {
    return validator(message);
  }

  return {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const listSessionsMessage: ListSessionsMessage = {type: 'list_sessions'};

  if ('limit' in message && message.limit !== undefined) {
    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0) {
      return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
    }
    listSessionsMessage.limit = message.limit;
  }

  if ('before' in message && message.before !== undefined) {
    if (typeof message.before !== 'object' || message.before === null) {
      return {valid: false, error: 'list_sessions before must be an object'};
    }
    const before = message.before as Record<string, unknown>;
    if (typeof before.sessionId !== 'string' || before.sessionId.length < 1 || before.sessionId.length > 128) {
      return {valid: false, error: 'list_sessions before.sessionId must be 1-128 chars'};
    }
    if (typeof before.updatedAt !== 'string' && typeof before.updatedAt !== 'number') {
      return {valid: false, error: 'list_sessions before.updatedAt must be string or number'};
    }
    const date = new Date(before.updatedAt);
    if (isNaN(date.getTime())) {
      return {valid: false, error: 'list_sessions before.updatedAt must be a valid date'};
    }
    listSessionsMessage.before = {
      sessionId: before.sessionId,
      updatedAt: before.updatedAt,
    };
  }

  return {valid: true, data: listSessionsMessage};
}

