it('rejects list_sessions with non-integer or negative limit', () => {
  expect(validateMessage({type: 'list_sessions', limit: 1.5}).valid).toBe(false);
  expect(validateMessage({type: 'list_sessions', limit: -1}).valid).toBe(false);
});

it('rejects list_sessions with malformed before', () => {
  expect(validateMessage({type: 'list_sessions', before: 'not-an-object'}).valid).toBe(false);
  expect(validateMessage({type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}}).valid).toBe(
    false
  );
  expect(
    validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}}).valid
  ).toBe(false);
  expect(
    validateMessage({
      type: 'list_sessions',
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)},
    }).valid
  ).toBe(false);
});

it('strips unknown fields like userId from list_sessions', () => {
  const result = validateMessage({type: 'list_sessions', userId: 'u1'});
  expect(result).toEqual({valid: true, data: {type: 'list_sessions'}});
});

